function evidence = f90_xbatt07_extract_candidate_evidence( ...
        modelPath, outputDir)
%F90_XBATT07_EXTRACT_CANDIDATE_EVIDENCE Replay the public BMS contract.
arguments
    modelPath (1,1) string
    outputDir (1,1) string
end
[taskRoot, sharedRoot] = localRoots("F90-XBATT-07");
addpath(sharedRoot, "-begin");
cleanup = onCleanup(@() rmpath(sharedRoot)); %#ok<NASGU>
official = jsondecode(fileread(simuverity_official_scenarios_path()));
spec = struct( ...
    "schema", "simuverity.f90-xbatt07-evidence.v1", ...
    "task_id", "F90-XBATT-07", ...
    "scenarios", official.scenarios, ...
    "output_contract", localOutputs, ...
    "input_builder", @localInputs, ...
    "requested_input_builder", @localRequested, ...
    "stop_time", @(~,~) 25.0, ...
    "postprocess", @localPostprocess, ...
    "static_audit", @localAudit, ...
    "evidence_sample_s", 0.1);
evidence = simuverity_run_candidate_evidence( ...
    modelPath, outputDir, spec);
end

function rows = localOutputs
rows = localRows(["supervisor_state", "contactor_commands", ...
    "current_limits", "cell_extrema", "fault_state"], [5 6 2 4 8]);
for k = [1 2 5], rows(k).interpolation = "previous"; end
end

function inputs = localInputs(scenario, ~)
voltage = ((double(scenario.cell_min_V) + ...
    double(scenario.cell_max_V)) / 2) .* ones(96, 1);
voltage(1:2) = [double(scenario.cell_min_V); ...
    double(scenario.cell_max_V)];
temperature = ((double(scenario.cell_min_C) + ...
    double(scenario.cell_max_C)) / 2) .* ones(96, 1);
temperature(1:2) = [double(scenario.cell_min_C); ...
    double(scenario.cell_max_C)];
inputs = struct("bms_input", struct( ...
    "cell_voltages_V", voltage, ...
    "cell_temperatures_C", temperature, ...
    "pack_voltage_V", double(scenario.pack_voltage_V), ...
    "pack_current_A", double(scenario.pack_current_A), ...
    "charger_dc_voltage_V", double(scenario.charger_dc_voltage_V), ...
    "inverter_dc_voltage_V", double(scenario.inverter_dc_voltage_V), ...
    "state_request", double(scenario.state_request)));
end

function requested = localRequested(scenario, ~)
requested = rmfield(scenario, "id");
end

function row = localPostprocess(row, outputs, ~, ~)
t = double(outputs.time_s(:));
supervisor = double(outputs.supervisor_state);
commands = double(outputs.contactor_commands);
limits = double(outputs.current_limits);
extrema = double(outputs.cell_extrema);
faults = double(outputs.fault_state);
logs = struct;
logs.log_bms_state = localLog(t, supervisor(:,1));
logs.log_charger_state = localLog(t, supervisor(:,2));
logs.log_inverter_state = localLog(t, supervisor(:,3));
commandNames = ["log_cmd_PosCntctChgrCmd", ...
    "log_cmd_PreChrgRelayChgrCmd", "log_cmd_NegCntctChgrCmd", ...
    "log_cmd_PosCntctInvtrCmd", "log_cmd_PreChrgRelayInvtrCmd", ...
    "log_cmd_NegCntctInvtrCmd"];
for k = 1:numel(commandNames)
    logs.(commandNames(k)) = localLog(t, commands(:,k));
end
limitNames = ["log_limit_DischargeCurrentLimit", ...
    "log_limit_ChargeCurrentLimit"];
for k = 1:numel(limitNames)
    logs.(limitNames(k)) = localLog(t, limits(:,k));
end
extremaNames = ["log_extrema_MinCellVolt", "log_extrema_MaxCellVolt", ...
    "log_extrema_MinCellTemp", "log_extrema_MaxCellTemp"];
for k = 1:numel(extremaNames)
    logs.(extremaNames(k)) = localLog(t, extrema(:,k));
end
logs.log_critical_fault = localLog(t, supervisor(:,4));
logs.log_limp_mode = localLog(t, supervisor(:,5));
faultNames = ["log_fault_PackOverCurrFlt", ...
    "log_fault_CellHighTempFlt", "log_fault_CellLowTempFlt", ...
    "log_fault_VoltSensorFlt", "log_fault_CellOverVoltFlt", ...
    "log_fault_CellUnderVoltFlt", "log_fault_ChrgCntctFlt", ...
    "log_fault_InvtrCntctFlt"];
for k = 1:numel(faultNames)
    logs.(faultNames(k)) = localLog(t, faults(:,k));
end
row.logs = logs;
row.outputs = outputs;
row.valid = row.output_contract.all_required_pass && ...
    numel(t) >= 200 && t(1) <= 1e-9 && t(end) >= 24.9;
end

function log = localLog(time, data)
log = struct("time", time, "data", double(data(:)));
end

function audit = localAudit(model, spec)
structure = simuverity_candidate_structure( ...
    model, string({spec.output_contract.name})');
audit = struct( ...
    "connected_public_output_count", structure.connected_output_count, ...
    "nontrivial_public_output_source_count", ...
        structure.nontrivial_output_source_count, ...
    "dynamic_state_block_count", structure.dynamic_block_count, ...
    "feedback_cycle_present", structure.signal_cycle_present, ...
    "core_path_qualified", ...
        structure.connected_output_count == numel(spec.output_contract) && ...
        structure.nontrivial_output_source_count == ...
            numel(spec.output_contract) && ...
        structure.dynamic_block_count >= 1);
end

function rows = localRows(names, widths)
rows = repmat(struct("name", "", "evidence_name", "", ...
    "width", 0, "interpolation", "linear"), numel(names), 1);
for k = 1:numel(names)
    rows(k).name = names(k);
    rows(k).evidence_name = names(k);
    rows(k).width = widths(k);
end
end

function [taskRoot, sharedRoot] = localRoots(taskId)
scriptRoot = fileparts(mfilename("fullpath"));
tasksRoot = fileparts(scriptRoot);
sharedRoot = fullfile(tasksRoot, "_shared");
repoRoot = tasksRoot;
for k = 1:3, repoRoot = fileparts(repoRoot); end
taskRoot = string(getenv("SIMUVERITY_TASK_ROOT"));
end
